package iso.tool; import java.nio.file.*; import java.util.*;
public final class Main { public static void main(String[] a)throws Exception{Path root=Paths.get(a.length>0?a[0]:".");Path out=Paths.get(a.length>1?a[1]:"iso-tool-output");Files.createDirectories(out.resolve("manifests"));DependencyDetector.write(out.resolve("manifests/dependencies.json"));List<Path>py=PythonParityScanner.scan(root);Files.write(out.resolve("manifests/python-modules.txt"),py.stream().map(Path::toString).sorted().collect(java.util.stream.Collectors.toList()));System.out.println("ISO-Tool Java parity scan: "+py.size()+" Python modules");} }
